import React, { useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { Bed, Bath, Car, Maximize, MapPin, Phone, Mail, Share2, Heart, ChevronLeft, ChevronRight, CheckCircle, ArrowLeft } from 'lucide-react';
import { MOCK_PROPERTIES, formatPrice, STATUS_LABELS } from '../data/mockData';
import { useAuth } from '../context/AuthContext';
import './PropertyDetail.css';

export default function PropertyDetail() {
  const { id } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();
  const property = MOCK_PROPERTIES.find(p => p.id === Number(id));

  const [imgIndex, setImgIndex] = useState(0);
  const [form, setForm] = useState({ name: user?.name || '', email: user?.email || '', phone: '', date: '', time: '', message: '' });
  const [submitted, setSubmitted] = useState(false);
  const [wishlist, setWishlist] = useState(() => {
    const saved = localStorage.getItem('propconnect_wishlist');
    return saved ? JSON.parse(saved) : [];
  });

  if (!property) return (
    <div className="container section">
      <div className="empty-state">
        <h3>Property not found</h3>
        <Link to="/listings" className="btn btn-primary" style={{ marginTop: '1rem' }}>Back to Listings</Link>
      </div>
    </div>
  );

  const status = STATUS_LABELS[property.status] || STATUS_LABELS.available;

  const toggleWishlist = () => {
    const updated = wishlist.includes(property.id)
      ? wishlist.filter(i => i !== property.id)
      : [...wishlist, property.id];
    setWishlist(updated);
    localStorage.setItem('propconnect_wishlist', JSON.stringify(updated));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!user) { navigate('/login'); return; }
    setSubmitted(true);
  };

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const specs = [
    property.bedrooms != null && { label: 'Bedrooms', value: property.bedrooms, icon: <Bed size={18} /> },
    property.bathrooms != null && { label: 'Bathrooms', value: property.bathrooms, icon: <Bath size={18} /> },
    property.garages != null && { label: 'Garages', value: property.garages, icon: <Car size={18} /> },
    property.parking != null && { label: 'Parking', value: property.parking, icon: <Car size={18} /> },
    property.floorSize && { label: 'Floor Size', value: `${property.floorSize}m²`, icon: <Maximize size={18} /> },
    property.standSize && { label: 'Stand Size', value: `${property.standSize}m²`, icon: <Maximize size={18} /> },
  ].filter(Boolean);

  return (
    <div className="property-detail">
      <div className="container" style={{ paddingTop: '1.5rem' }}>
        <button className="btn btn-ghost back-btn" onClick={() => navigate(-1)}>
          <ArrowLeft size={16} /> Back to Listings
        </button>
      </div>

      {/* Gallery */}
      <div className="gallery-section">
        <div className="gallery-main">
          <img src={property.images[imgIndex]} alt={property.title} />
          {property.images.length > 1 && (
            <>
              <button className="gallery-nav prev" onClick={() => setImgIndex(i => (i - 1 + property.images.length) % property.images.length)}>
                <ChevronLeft size={22} />
              </button>
              <button className="gallery-nav next" onClick={() => setImgIndex(i => (i + 1) % property.images.length)}>
                <ChevronRight size={22} />
              </button>
              <div className="gallery-dots">
                {property.images.map((_, i) => (
                  <button key={i} className={i === imgIndex ? 'active' : ''} onClick={() => setImgIndex(i)} />
                ))}
              </div>
            </>
          )}
        </div>
        {property.images.length > 1 && (
          <div className="gallery-thumbs">
            {property.images.map((img, i) => (
              <button key={i} className={`thumb ${i === imgIndex ? 'active' : ''}`} onClick={() => setImgIndex(i)}>
                <img src={img} alt="" />
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="container detail-layout">
        {/* Main Info */}
        <div className="detail-main">
          <div className="detail-header">
            <div>
              <div className="detail-badges">
                <span className={`badge ${status.cls}`}>{status.label}</span>
                <span className="badge badge-muted">{property.listingType === 'rental' ? 'To Let' : 'For Sale'}</span>
                <span className="badge badge-muted" style={{ textTransform: 'capitalize' }}>{property.type}</span>
              </div>
              <h1>{property.title}</h1>
              <p className="detail-location"><MapPin size={16} /> {property.address}, {property.suburb}, {property.city}</p>
            </div>
            <div className="detail-price-wrap">
              <div className="detail-price">{formatPrice(property.price, property.listingType)}</div>
              <div className="detail-actions">
                <button className={`btn btn-ghost ${wishlist.includes(property.id) ? 'wishlisted' : ''}`} onClick={toggleWishlist}>
                  <Heart size={16} fill={wishlist.includes(property.id) ? 'currentColor' : 'none'} />
                  {wishlist.includes(property.id) ? 'Saved' : 'Save'}
                </button>
                <button className="btn btn-ghost" onClick={() => navigator.clipboard?.writeText(window.location.href)}>
                  <Share2 size={16} /> Share
                </button>
              </div>
            </div>
          </div>

          {/* Specs */}
          {specs.length > 0 && (
            <div className="specs-grid">
              {specs.map(s => (
                <div key={s.label} className="spec-item">
                  <div className="spec-icon">{s.icon}</div>
                  <div>
                    <div className="spec-value">{s.value}</div>
                    <div className="spec-label">{s.label}</div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Description */}
          <div className="detail-section">
            <h2>About This Property</h2>
            <p>{property.description}</p>
          </div>

          {/* Amenities */}
          {property.amenities.length > 0 && (
            <div className="detail-section">
              <h2>Amenities & Features</h2>
              <div className="amenities-grid">
                {property.amenities.map(a => (
                  <div key={a} className="amenity-item">
                    <CheckCircle size={16} /> {a}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Sidebar */}
        <div className="detail-sidebar">
          {/* Agent Card */}
          <div className="card agent-card">
            <div className="agent-card-header">
              <img src={property.agentPhoto} alt={property.agentName} />
              <div>
                <h3>{property.agentName}</h3>
                <p>Property Agent</p>
              </div>
            </div>
            <div className="agent-contacts">
              <a href={`tel:${property.agentPhone}`} className="btn btn-outline agent-contact-btn">
                <Phone size={15} /> {property.agentPhone}
              </a>
              <a href={`mailto:${property.agentEmail}`} className="btn btn-ghost agent-contact-btn">
                <Mail size={15} /> Email Agent
              </a>
            </div>
          </div>

          {/* Viewing Request */}
          <div className="card viewing-card">
            <div className="viewing-card-header">
              <h3>Request a Viewing</h3>
              <p>Fill in your details and we'll confirm your appointment</p>
            </div>
            {submitted ? (
              <div className="viewing-success">
                <CheckCircle size={40} />
                <h4>Request Submitted!</h4>
                <p>The agent will contact you shortly to confirm your viewing.</p>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="viewing-form">
                <div className="form-group">
                  <label>Full Name</label>
                  <input className="form-control" required value={form.name} onChange={e => set('name', e.target.value)} placeholder="Your full name" />
                </div>
                <div className="form-group">
                  <label>Email Address</label>
                  <input className="form-control" type="email" required value={form.email} onChange={e => set('email', e.target.value)} placeholder="your@email.com" />
                </div>
                <div className="form-group">
                  <label>Phone Number</label>
                  <input className="form-control" required value={form.phone} onChange={e => set('phone', e.target.value)} placeholder="07x xxx xxxx" />
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label>Preferred Date</label>
                    <input className="form-control" type="date" required value={form.date} onChange={e => set('date', e.target.value)} min={new Date().toISOString().split('T')[0]} />
                  </div>
                  <div className="form-group">
                    <label>Preferred Time</label>
                    <input className="form-control" type="time" required value={form.time} onChange={e => set('time', e.target.value)} />
                  </div>
                </div>
                <div className="form-group">
                  <label>Message (Optional)</label>
                  <textarea className="form-control" rows={3} value={form.message} onChange={e => set('message', e.target.value)} placeholder="Any specific questions or requirements..." />
                </div>
                <button type="submit" className="btn btn-primary" style={{ width: '100%' }}>
                  {user ? 'Submit Viewing Request' : 'Sign In to Request Viewing'}
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
